      rowsPerPage: 50,
    });

    return {
      selected: ref([]),
      initialPagination,
      columns,
      rows,
      currentItem,
      onRowClick,

      pagination,
      clearTheItem,
      dragStart,
      dragEnd,
    };
  },
};
</script>

